const salesText = readFileSync('sales.csv', 'utf8');
const pricingText = readFileSync('pricing-sources.md', 'utf8');
const rows = parseCsv(salesText);

const monthly = new Map();
for (const row of rows) {
  const month = row.date.slice(0, 7);
  monthly.set(month, (monthly.get(month) ?? 0) + row.amount);
}

